sp_widget.client_script:
function($scope, $uibModal, $location, $window,spUtil, $timeout) {
	var c = this;
	//intialize

	if(c.data.infoMessage) {
		spUtil.addInfoMessage(c.data.infoMessage);

		$timeout(function() {
			$("#uiNotificationContainer").find(".alert-msg").attr("tabindex",0);
			$("#uiNotificationContainer").find(".alert-msg").attr("role","group");
			$("#uiNotificationContainer").find(".alert-msg").focus();
		});
	}

	var parentContainerConfig = c.data.parentContainerConfig;
	console.log("HEEY");
	if (c.data.showModal){
		console.log(parentContainerConfig);
		if(parentContainerConfig && ((parentContainerConfig["parent_container_class"] == "hidden-xs" && screen.width >= 768) || (parentContainerConfig["parent_container_class"] == "visible-xs" && screen.width < 768))) {
			console.log("hii");
			$scope.modalInstance = $uibModal.open({
				templateUrl: 'externalRegistrationResponseModalHCK',
				scope: $scope, 
			});
		}
	}

	c.login = function () {
		$scope.modalInstance.close();
		$location.url('?id='+ c.data.login_page);
	};

	c.cancel = function() {
		$scope.modalInstance.close();
	};

	var deregisterListener;
	if(!c.data.isLoggedIn) {
		deregisterListener = $rootScope.$on('$locationChangeStart', function (event, next, current) {
			var	finalUrl = $rootScope.portal.url_suffix ;
			$window.sessionStorage.setItem('navBackUri', '/'+ finalUrl);
			deregisterListener();
		});	
	}
}

sp_widget.script:
(function () {
  /* populate the 'data' object */
  /* e.g., data.table = $sp.getValue('table'); */
  /*If GlideRecord/GlideRecordSecure is called, please follow the below guidelines,
	Remediation
	------------------
	1. If possible, set the widget non-public, i.e. "<public>false<public>". Assess if the widget needs to be really public.
	2. If possible, restrict the table names passed into GlideRecord/GlideRecordSecure. This can be done by completely hardcoding the table name.
	3. As a last resort, ensure the table accessed by the GlideRecord/GlideRecordSecure object are explicitly defined in the "Public Table Allow List" in related list section of the widget. And also make security API call before the GlideRecord/GlideRecordSecure call.
	Below is sample example code for calling secure API
	-----------------------------------------------------------------------------------------------------------------------------------------
	if(!new global.SPWidgetAccessControl().hasPublicAccess(options.table, $sp, options, input)){
		gs.warn("Deny access to table which is not public: " + options.table);
		data.isValid = false;
		return;
	}
	var gr = new GlideRecordSecure(options.table);*/
  data.ERROR = "error";
  data.SUCCESS = "success";
  data.isLoggedIn = gs.getSession().isLoggedIn();
  data.isCSPPortal =
    $sp.getPortalRecord().getValue("sys_id") ==
    HackathonExternalRegConstants.CSP_PORTAL_ID;
  data.parentContainerConfig = options.widget_parameters
    ? JSON.parse(options.widget_parameters)
    : "";

  if (!data.isLoggedIn) {
    data.register_response = $sp.getParameter("register_response");
    if (data.register_response) {
      var msg_response = gs.getSession().getClientData("reg_resp_message"),
        msg_status = gs.getSession().getClientData("reg_resp_status"),
        userName = gs.getSession().getClientData("reg_user_name");
      gs.getSession().putClientData("reg_resp_message", "");
      gs.getSession().putClientData("reg_resp_status", "");

      gs.info(
        "msg_response: " +
          msg_response +
          ", msg_status: " +
          msg_status +
          ", userName: " +
          userName
      );

			gs.info(data.register_response ==
          HackathonExternalRegConstants.SUCESS_REGISTRATION &&
        !gs.nil(userName));

			gs.info("register_response: " + data.register_response);
      gs.info("constant: " + HackathonExternalRegConstants.SUCESS_REGISTRATION);
      gs.info("userName: " + userName);

      if (msg_status == data.SUCCESS) {
        if (data.register_response != HackathonExternalRegConstants.SUCESS_REGISTRATION)
          data.infoMessage = msg_response;
        else if (!data.isCSPPortal) data.infoMessage = msg_response;
      } else if (msg_status == data.ERROR) gs.addErrorMessage(msg_response);
      if (
        //data.isCSPPortal &&
        data.register_response ==
          HackathonExternalRegConstants.SUCESS_REGISTRATION &&
        !gs.nil(userName)
      ) {
        var userId = "<br/><b>" + userName + "</b>";
        data.msg = {};
        data.msg.greet = gs.getMessage("Congratulations!");
        data.msg.successText = gs.getMessage(
          "You have successfully registered with Username: {0}",
          userId
        );
        data.msg.loginText = gs.getMessage("Please click here to login");
        data.showModal = true;
        data.login_page = $sp.getDisplayValue("login_page") || "csm_login";
        if (!data.login_page) data.login_page = "login";
      }
    }
  }
})();
